#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define V 50257
#define M 50000
#define D 768
float*W;long WN;
unsigned char tb[4000000];int to[V],tl[V],np1[M],np2[M];
#define HN 131072
int ht[HN];
int b2u[256],u2b[512];
unsigned Hh(unsigned char*s,int n){unsigned h=2166136261;for(int i=0;i<n;i++){h^=s[i];h*=16777619;}return h;}
int find(unsigned char*s,int n){unsigned h=Hh(s,n);for(int i=h%HN;;i=(i+1)%HN){if(!ht[i])return-1;int id=ht[i]-1;if(tl[id]==n&&!memcmp(tb+to[id],s,n))return id;}}
void add(int id){unsigned h=Hh(tb+to[id],tl[id]);for(int i=h%HN;;i=(i+1)%HN)if(!ht[i]){ht[i]=id+1;return;}}
void initb(){int j=0;for(int i=0;i<256;i++)b2u[i]=-1;for(int i=33;i<127;i++)b2u[i]=i;for(int i=161;i<173;i++)b2u[i]=i;for(int i=174;i<256;i++)b2u[i]=i;for(int i=0;i<256;i++)if(b2u[i]<0)b2u[i]=256+j++;for(int i=0;i<256;i++)u2b[b2u[i]]=i;}
void loadbpe(char*fn){initb();int p=0;for(int i=0;i<256;i++){to[i]=p;tb[p++]=i;tl[i]=1;add(i);}FILE*f=fopen(fn,"rb");char ln[512];fgets(ln,512,f);for(int r=0;r<M;r++){fgets(ln,512,f);int sp=0;while(ln[sp]!=' ')sp++;unsigned char b[64];int n=0;for(int i=0;i<sp;){int c=ln[i];if(c<128)b[n++]=u2b[c],i++;else{b[n++]=u2b[((c&31)<<6)|(ln[i+1]&63)];i+=2;}}int id1=find(b,n);n=0;int l2=strlen(ln+sp+1)-1;for(int i=0;i<l2;){int c=ln[sp+1+i];if(c<128)b[n++]=u2b[c],i++;else{b[n++]=u2b[((c&31)<<6)|(ln[sp+1+i+1]&63)];i+=2;}}int id2=find(b,n);int id=256+r;to[id]=p;memcpy(tb+p,tb+to[id1],tl[id1]);p+=tl[id1];memcpy(tb+p,tb+to[id2],tl[id2]);p+=tl[id2];tl[id]=p-to[id];add(id);np1[r]=id1;np2[r]=id2;}fclose(f);}
int tok(char*s,int*tk){int n=0,len=strlen(s);for(int i=0;i<len;){int st=i;if(s[i]==' '){i++;if(i>=len){tk[n++]=32;break;}}while(i<len&&s[i]!=' ')i++;int wt[128],wn=0;for(int j=st;j<i;j++)wt[wn++]=s[j];while(wn>1){int best=-1,bestr=M;for(int a=0;a<wn-1;a++){int r=0;while(r<M&&!(np1[r]==wt[a]&&np2[r]==wt[a+1]))r++;if(r<M&&r<bestr){bestr=r;best=a;}}if(best<0)break;wt[best]=256+bestr;for(int b=best+1;b<wn-1;b++)wt[b]=wt[b+1];wn--;}for(int j=0;j<wn;j++)tk[n++]=wt[j];}return n;}
int main(int argc,char**argv){fprintf(stderr,"loading bpe...");loadbpe(argv[1]);fprintf(stderr,"done\ntokenizing...");static int tk[1024];int T=tok(argv[2],tk);fprintf(stderr,"done T=%d\n",T);for(int i=0;i<T;i++)printf("%d ",tk[i]);printf("\n");for(int i=0;i<T;i++){for(int j=0;j<tl[tk[i]];j++)putchar(tb[to[tk[i]]+j]);}printf("\n");return 0;}
